import { router } from "expo-router";

/**
 * Open a Retention screen. The cast is because expo-router's typed routes are generated by the bundler, and a
 * folder added while it isn't running stays unknown to the type check until the next start (the call sheet casts
 * `/lead/:id` the same way).
 */
export const openRetention = (path: "/retention" | "/retention/waiting" | "/retention/win-back" | `/retention/${string}`) => router.push(path as never);
